import { useState, useRef, useCallback, useEffect } from 'react';
import { Check, X, ZoomIn, ZoomOut, RotateCcw } from 'lucide-react';

interface AvatarCropperProps {
  imageSrc: string;
  onCrop: (croppedImage: string) => void;
  onCancel: () => void;
}

export default function AvatarCropper({ imageSrc, onCrop, onCancel }: AvatarCropperProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [offsetX, setOffsetX] = useState(0);
  const [offsetY, setOffsetY] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [imgLoaded, setImgLoaded] = useState(false);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const containerSize = 300;

  useEffect(() => {
    const img = new Image();
    img.onload = () => {
      imgRef.current = img;
      const initialScale = Math.max(containerSize / img.width, containerSize / img.height, 1);
      setScale(initialScale);
      setOffsetX(0);
      setOffsetY(0);
      setImgLoaded(true);
    };
    img.src = imageSrc;
  }, [imageSrc]);

  const drawPreview = useCallback(() => {
    const canvas = canvasRef.current;
    const img = imgRef.current;
    if (!canvas || !img) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = containerSize * dpr;
    canvas.height = containerSize * dpr;
    canvas.style.width = containerSize + 'px';
    canvas.style.height = containerSize + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    ctx.clearRect(0, 0, containerSize, containerSize);

    const scaledW = img.width * scale;
    const scaledH = img.height * scale;
    const x = (containerSize - scaledW) / 2 + offsetX;
    const y = (containerSize - scaledH) / 2 + offsetY;

    ctx.drawImage(img, x, y, scaledW, scaledH);

    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, containerSize, containerSize);
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillRect(0, 0, containerSize, containerSize);
    ctx.globalCompositeOperation = 'source-over';

    ctx.drawImage(img, x, y, scaledW, scaledH);
  }, [scale, offsetX, offsetY, containerSize]);

  useEffect(() => {
    if (imgLoaded) {
      drawPreview();
    }
  }, [imgLoaded, scale, offsetX, offsetY, drawPreview]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setDragging(true);
    setDragStart({ x: e.clientX - offsetX, y: e.clientY - offsetY });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!dragging) return;
    setOffsetX(e.clientX - dragStart.x);
    setOffsetY(e.clientY - dragStart.y);
  };

  const handleMouseUp = () => setDragging(false);

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 1) {
      setDragging(true);
      setDragStart({ x: e.touches[0].clientX - offsetX, y: e.touches[0].clientY - offsetY });
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!dragging || e.touches.length !== 1) return;
    setOffsetX(e.touches[0].clientX - dragStart.x);
    setOffsetY(e.touches[0].clientY - dragStart.y);
  };

  const handleTouchEnd = () => setDragging(false);

  const handleZoomIn = () => setScale((s) => Math.min(s + 0.1, 3));
  const handleZoomOut = () => setScale((s) => Math.max(s - 0.1, 0.5));
  const handleReset = () => {
    if (!imgRef.current) return;
    const initialScale = Math.max(containerSize / imgRef.current.width, containerSize / imgRef.current.height, 1);
    setScale(initialScale);
    setOffsetX(0);
    setOffsetY(0);
  };

  const handleConfirm = () => {
    const canvas = document.createElement('canvas');
    const size = 512;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    if (!ctx || !imgRef.current) return;

    const scaledW = imgRef.current.width * scale;
    const scaledH = imgRef.current.height * scale;
    const x = (containerSize - scaledW) / 2 + offsetX;
    const y = (containerSize - scaledH) / 2 + offsetY;

    const ratio = size / containerSize;
    ctx.drawImage(
      imgRef.current,
      -x * ratio,
      -y * ratio,
      imgRef.current.width * scale * ratio,
      imgRef.current.height * scale * ratio
    );

    onCrop(canvas.toDataURL('image/jpeg', 0.85));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="glass-card rounded-2xl p-6 max-w-sm w-full shadow-soft-xl animate-scale-in">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-semibold text-dream-slate-800">裁剪头像</h3>
          <button
            onClick={onCancel}
            className="p-2 rounded-lg hover:bg-dream-blue-50 text-dream-blue-400 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div
          ref={containerRef}
          className="relative mx-auto rounded-xl overflow-hidden cursor-grab active:cursor-grabbing select-none"
          style={{ width: containerSize, height: containerSize }}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          <canvas
            ref={canvasRef}
            className="w-full h-full"
          />
          <div className="absolute inset-0 border-2 border-white/60 rounded-xl pointer-events-none" />
          <div className="absolute inset-0 shadow-[inset_0_0_0_9999px_rgba(0,0,0,0.3)] rounded-xl pointer-events-none" />
        </div>

        <p className="text-xs text-dream-blue-400 text-center mt-3">
          拖动图片调整位置，图片越界部分会自动裁剪为正方形
        </p>

        <div className="flex items-center justify-center gap-3 mt-4">
          <button
            onClick={handleZoomOut}
            className="p-2.5 rounded-xl bg-dream-blue-50 text-dream-blue-600 hover:bg-dream-blue-100 transition-colors"
          >
            <ZoomOut className="w-4 h-4" />
          </button>
          <span className="text-sm text-dream-slate-600 font-medium min-w-12 text-center">
            {Math.round(scale * 100)}%
          </span>
          <button
            onClick={handleZoomIn}
            className="p-2.5 rounded-xl bg-dream-blue-50 text-dream-blue-600 hover:bg-dream-blue-100 transition-colors"
          >
            <ZoomIn className="w-4 h-4" />
          </button>
          <button
            onClick={handleReset}
            className="p-2.5 rounded-xl bg-dream-blue-50 text-dream-blue-600 hover:bg-dream-blue-100 transition-colors"
          >
            <RotateCcw className="w-4 h-4" />
          </button>
        </div>

        <div className="flex gap-3 mt-5">
          <button
            onClick={onCancel}
            className="flex-1 py-2.5 rounded-xl border border-dream-blue-200 text-dream-slate-600 text-sm font-medium hover:bg-dream-blue-50 transition-colors"
          >
            取消
          </button>
          <button
            onClick={handleConfirm}
            className="flex-1 py-2.5 rounded-xl gradient-btn text-white text-sm font-medium flex items-center justify-center gap-2"
          >
            <Check className="w-4 h-4" />
            确认裁剪
          </button>
        </div>
      </div>
    </div>
  );
}