import { useState, useEffect } from 'react';
import { RefreshCw, X, Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';

interface PWAUpdatePromptProps {
  onUpdate: () => void;
}

export default function PWAUpdatePrompt({ onUpdate }: PWAUpdatePromptProps) {
  const [isVisible, setIsVisible] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), 500);
    return () => clearTimeout(timer);
  }, []);

  const handleUpdate = () => {
    setIsUpdating(true);
    onUpdate();
  };

  const handleDismiss = () => {
    setIsVisible(false);
  };

  if (!isVisible) return null;

  return (
    <div className="fixed top-4 left-4 right-4 z-50 md:left-auto md:right-4 md:w-96 animate-fade-in-down">
      <div className={cn(
        'rounded-2xl glass-card shadow-soft-lg',
        'backdrop-blur-xl'
      )}>
        <div className="flex items-start gap-3 p-4">
          <div className="flex-shrink-0 w-12 h-12 rounded-xl gradient-bg flex items-center justify-center shadow-glow-soft">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="font-display font-semibold text-dream-slate-800">发现新版本</h3>
            <p className="mt-1 text-sm text-dream-blue-500">
              工作台已更新，点击立即刷新体验最新版本
            </p>
          </div>
          <button
            onClick={handleDismiss}
            className="flex-shrink-0 p-1 rounded-lg text-dream-blue-400 hover:text-dream-blue-600 hover:bg-dream-blue-50 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        <div className="px-4 pb-4">
          <div className="flex gap-2">
            <button
              onClick={handleUpdate}
              disabled={isUpdating}
              className={cn(
                'flex-1 px-4 py-2.5 rounded-xl text-sm font-medium',
                'gradient-btn text-white shadow-soft',
                'hover:shadow-soft-lg active:scale-95',
                'transition-all duration-200',
                'disabled:opacity-50 disabled:cursor-not-allowed'
              )}
            >
              {isUpdating ? (
                <span className="flex items-center justify-center gap-2">
                  <RefreshCw className="w-4 h-4 animate-spin" />
                  更新中...
                </span>
              ) : (
                '立即更新'
              )}
            </button>
            <button
              onClick={handleDismiss}
              className={cn(
                'px-4 py-2.5 rounded-xl text-sm font-medium',
                'bg-dream-blue-50 text-dream-blue-600',
                'hover:bg-dream-blue-100 active:scale-95',
                'transition-all duration-200'
              )}
            >
              稍后
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
